-- Migration 20261123040000: 凭证复核闸
-- 创建时间: 2026-11-23
-- 描述:
--   账套维度开关 review_required:打开后凭证必须先复核通过(review_status=2)才能过账。
--   fin_voucher 的 review_status/reviewed_by/reviewed_at/review_comment 四列在建表时已预留,
--   本次只加账套开关,不动凭证表(避免多会话同时改一张大表的列序)。
-- 幂等安全:IF NOT EXISTS。

ALTER TABLE "fin_ledger" ADD COLUMN IF NOT EXISTS "review_required" boolean DEFAULT false NOT NULL;
